import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { countdown } from '../../common/format';
import { currentCalendar } from '../../common/advent';
/** Fetches the calendar into the shared store, once a page load. */
export function load(store) {
  if (store.state !== 'idle') return;
  store.state = 'loading';
  currentCalendar().then(calendar => store.calendar = calendar).catch(() => {
    /* app.request already showed the alert */
  }).finally(() => {
    store.state = 'done';
    m.redraw();
  });
}

/**
 * "Today's door": the current calendar's door number and whether the viewer
 * has opened it, with a link to the calendar. Never what is behind a door:
 * it only ever asks the server for the calendar's summary fields.
 */
export class TodayDoor extends Component {
  view() {
    const c = this.attrs.store.calendar;
    if (!c) return null;
    const t = (key, params = {}) => app.translator.trans(`ernestdefoe-giveaways.forum.advent.widget.${key}`, params);
    const running = c.today >= 1;
    const href = app.route('giveaways.advent', {
      slug: c.slug
    });
    return m("div", {
      className: 'AdventToday' + (c.todayOpened ? ' is-opened' : '')
    }, m(Link, {
      className: "AdventToday-door",
      href: href,
      "aria-hidden": "true",
      tabindex: "-1"
    }, running ? c.today : m(Icon, {
      name: "fas fa-door-closed"
    })), m("div", {
      className: "AdventToday-body"
    }, m(Link, {
      className: "AdventToday-title",
      href: href
    }, c.title), m("div", {
      className: "AdventToday-state"
    }, !running ? t('starts_in', {
      time: countdown(c.nextOpensAt ?? null)
    }) : c.todayOpened ? [m(Icon, {
      name: "fas fa-check"
    }), ' ', t('opened', {
      day: c.today
    })] : t('waiting', {
      day: c.today
    })), running && c.nextOpensAt && m("div", {
      className: "AdventToday-next"
    }, t('next_in', {
      time: countdown(c.nextOpensAt)
    }))));
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/advent/todayBody', { load: load,TodayDoor: TodayDoor, });